package ozl.environment;
import java.io.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.*;
/** A separate live contract: source roots remain current and read-only. */
public final class LiveEnvironmentManifest {
 static final String BUDDY_HASH="eb79b9876332010733a8e0d7ce4fe0377846059a9e28859029e2a0fb449f6cf2";
 volatile boolean clientSelectionReady;final String serverComponents;final Path game,user,context,choices,buddy;final boolean vanilla;final Set<String> managed=new LinkedHashSet<String>();final Map<String,Path> selected=new LinkedHashMap<String,Path>();final List<String> components=new ArrayList<String>();final List<String> order=new ArrayList<String>();final List<String> ordinary=new ArrayList<String>();final boolean override;final Map<Path,String[]> jars=new LinkedHashMap<Path,String[]>();
 private LiveEnvironmentManifest(Map<String,List<String[]>> rows)throws Exception{game=path(single(rows,"game"),true);user=path(single(rows,"user"),true);context=path(single(rows,"context"),true);choices=path(single(rows,"choices"),true);String v=single(rows,"vanilla");if(!v.equals("true")&&!v.equals("false"))throw new IOException("invalid live mode");vanilla=v.equals("true");serverComponents=values(rows,"server-components").isEmpty()?null:single(rows,"server-components");if(serverComponents!=null&&!serverComponents.equals("follow-server")&&!serverComponents.equals("force-local"))throw new IOException("invalid server component mode");if(serverComponents!=null&&vanilla)throw new IOException("server session cannot hide native server discovery");if(context.startsWith(game)||context.startsWith(user)||!choices.startsWith(context)||choices.equals(context))throw new IOException("choices outside owned context");SafePaths.canonical(choices.resolve("mods/default.txt"),true,false);SafePaths.canonical(choices.resolve("mods/loaded.txt"),true,false);
  for(String[] row:values(rows,"managed")){arity(row,1);if(!managed.add(id(row[0])))throw new IOException("duplicate managed identity");}
  for(String[] row:values(rows,"selected")){arity(row,2);String id=id(row[0]);Path root=path(row[1],true);if(!managed.contains(id)||selected.put(id,root)!=null||vanilla&&!id.equals("OrangeLauncherSession"))throw new IOException("invalid selected identity");if(vanilla&&!root.startsWith(context))throw new IOException("vanilla bridge outside context");requireIdentity(root,id);}
  for(String[] row:values(rows,"jar")){arity(row,4);Path file=SafePaths.canonical(Paths.get(row[0]),true,false);if(vanilla||!row[2].matches("[a-f0-9]{64}")||!row[3].matches("true|false")||!row[1].matches("[A-Za-z_$][A-Za-z0-9_$]*(\\.[A-Za-z_$][A-Za-z0-9_$]*)*")||!selected.values().stream().anyMatch(file::startsWith)||jars.put(file,new String[]{row[1],row[2],row[3]})!=null)throw new IOException("invalid execution selection");}
  List<String[]> overrideRows=values(rows,"override");override=!overrideRows.isEmpty()&&single(rows,"override").equals("true");if(!overrideRows.isEmpty()&&!single(rows,"override").matches("true|false"))throw new IOException("invalid ordinary override");for(String[] row:values(rows,"ordinary")){arity(row,1);ordinary.add(id(row[0]));}if(!override&&!ordinary.isEmpty())throw new IOException("ordinary list without override");for(String[] row:values(rows,"component")){arity(row,1);String id=id(row[0]);if(!components.contains(id))components.add(id);}if(components.isEmpty())components.addAll(selected.keySet());for(String id:selected.keySet())if(!components.contains(id))throw new IOException("selected component absent from active merge");
  for(String[] row:values(rows,"order")){arity(row,1);String id=id(row[0]);if(!order.contains(id))order.add(id);}for(String id:components)if(!order.contains(id))order.add(id);
  List<String[]> b=values(rows,"buddy");if(b.size()>1)throw new IOException("duplicate Buddy");if(b.isEmpty())buddy=null;else{String[] row=b.get(0);arity(row,2);buddy=SafePaths.canonical(Paths.get(row[0]),true,false);if(vanilla||!buddy.startsWith(context)||!row[1].equals(BUDDY_HASH)||!sha(buddy).equals(BUDDY_HASH))throw new IOException("unsupported Buddy runtime; expected 2.3.4");}
 }
 static List<String[]> values(Map<String,List<String[]>> rows,String name){List<String[]> v=rows.get(name);return v==null?Collections.emptyList():v;}static void arity(String[] row,int n)throws IOException{if(row.length!=n)throw new IOException("invalid live record");}static String single(Map<String,List<String[]>> rows,String name)throws IOException{List<String[]> v=values(rows,name);if(v.size()!=1)throw new IOException("missing or repeated "+name);arity(v.get(0),1);return v.get(0)[0];}
 static Path path(String p,boolean directory)throws IOException{return SafePaths.canonical(Paths.get(p),true,directory);}
 // Mod IDs are logical names (including Workshop namespaces), never source paths.
 static String id(String id)throws IOException{if(id==null||id.trim().isEmpty()||!id.equals(id.trim())||id.length()>200)throw new IOException("invalid mod identity");for(int n=0;n<id.length();n++)if(Character.isISOControl(id.charAt(n))||",;={}".indexOf(id.charAt(n))>=0)throw new IOException("invalid mod identity");for(String part:id.split("[/\\\\]",-1))if(part.equals(".")||part.equals(".."))throw new IOException("mod identity contains traversal");return id.startsWith("\\")?id.substring(1):id;}
 static String sha(Path file)throws Exception{MessageDigest d=MessageDigest.getInstance("SHA-256");try(InputStream in=Files.newInputStream(file)){byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)d.update(b,0,n);}StringBuilder s=new StringBuilder();for(byte b:d.digest())s.append(String.format("%02x",b));return s.toString();}
 static LiveEnvironmentManifest read(Path file,String hash,Path cwd)throws Exception{SafePaths.canonical(file,true,false);if(hash==null||!hash.matches("(?i)[a-f0-9]{64}")||!sha(file).equalsIgnoreCase(hash))throw new IOException("live manifest changed");String[] lines=new String(SafePaths.bytes(file,2097152),StandardCharsets.UTF_8).split("\\r?\\n");if(lines.length==0||!lines[0].equals("OZLLIVE1"))throw new IOException("wrong live contract");Map<String,List<String[]>> rows=new LinkedHashMap<String,List<String[]>>();Set<String> keys=new HashSet<String>(Arrays.asList("game","user","context","choices","vanilla","managed","selected","jar","buddy","component","override","ordinary","order","server-components"));for(int i=1;i<lines.length;i++){String[] p=lines[i].split("\t",-1);if(!keys.contains(p[0]))throw new IOException("unknown live record");String[] v=new String[p.length-1];for(int n=1;n<p.length;n++)v[n-1]=new String(Base64.getDecoder().decode(p[n]),StandardCharsets.UTF_8);rows.computeIfAbsent(p[0],k->new ArrayList<String[]>()).add(v);}LiveEnvironmentManifest result=new LiveEnvironmentManifest(rows);if(!result.game.equals(SafePaths.canonical(cwd,true,true))||!file.startsWith(result.context))throw new IOException("live context binding mismatch");return result;}
 static Set<String> identities(Path root)throws Exception{SafePaths.canonical(root,true,true);List<Path> infos=new ArrayList<Path>();infos.add(root.resolve("mod.info"));try(DirectoryStream<Path> children=Files.newDirectoryStream(root)){int count=0;for(Path p:children){if(++count>10000)throw new IOException("too many mod directories");String name=p.getFileName().toString();if(name.equals("common")||name.matches("[0-9]+(\\.[0-9]+)*"))infos.add(p.resolve("mod.info"));}}Set<String> ids=new LinkedHashSet<String>();for(Path info:infos)if(Files.exists(info)){String text=new String(SafePaths.bytes(info,262144),StandardCharsets.UTF_8).replace("\uFEFF","");for(String line:text.split("\\r?\\n")){int at=line.indexOf('=');if(at>0&&line.substring(0,at).trim().equalsIgnoreCase("id"))ids.add(id(line.substring(at+1).trim()));}}return ids;}
 static void requireIdentity(Path root,String id)throws Exception{Set<String> ids=identities(root);if(ids.size()!=1||!ids.contains(id))throw new IOException("selected source identity changed: "+id);}
 void filter(List<String> roots)throws Exception{if(roots==null)throw new IOException("missing discovery list");List<String> keep=new ArrayList<String>();Set<Path> seen=new HashSet<Path>();if(!vanilla)for(String value:roots){Path root=path(value,true);Set<String> ids=identities(root);boolean managedRoot=ids.stream().anyMatch(managed::contains);if(managedRoot&&ids.size()>1)throw new IOException("mixed managed identities in "+root);if(!managedRoot&&seen.add(root))keep.add(root.toString());}for(Map.Entry<String,Path> entry:selected.entrySet()){requireIdentity(entry.getValue(),entry.getKey());if(seen.add(entry.getValue()))keep.add(entry.getValue().toString());}roots.clear();roots.addAll(keep);}
 boolean usesBuddyApproval(){return serverComponents!=null;}
 void filter(List<String> roots,boolean client,Set<String> serverIds)throws Exception{
  if(serverComponents==null){filter(roots);return;}
  // Before connection metadata exists, expose only the launch bridge and loader.
  // A menu scan otherwise caches a local same-ID source before Workshop arrives.
  if(!client||serverIds.isEmpty()&&!clientSelectionReady){List<String> initial=new ArrayList<String>();for(String value:Arrays.asList("ZombieBuddy","OrangeLauncherSession"))if(selected.containsKey(value)){Path root=selected.get(value);requireIdentity(root,value);initial.add(root.toString());}roots.clear();roots.addAll(initial);return;}
  if(roots==null)throw new IOException("missing discovery list");
  Set<String> forced=new HashSet<String>();if(serverComponents.equals("force-local"))for(String value:components)if(!value.equals("OrangeLauncherSession")&&!value.equals("ZombieBuddy")&&!serverIds.contains(value))forced.add(value);
  List<String> keep=new ArrayList<String>();Set<Path> seen=new HashSet<Path>();List<Path> nativeRoots=new ArrayList<Path>();Map<Path,Set<String>> identities=new LinkedHashMap<Path,Set<String>>();
  for(String value:roots){Path root=path(value,true);if(!identities.containsKey(root)){nativeRoots.add(root);identities.put(root,identities(root));}}
  for(Path root:nativeRoots){Set<String> ids=identities.get(root);boolean replaced=false;for(String value:ids){if(forced.contains(value)){replaced=true;break;}Path pin=selected.get(value);if(serverIds.contains(value)&&root.equals(pin)&&nativeRoots.stream().anyMatch(other->!other.equals(root)&&identities.get(other).contains(value))){replaced=true;break;}}
   if(replaced&&ids.size()>1)throw new IOException("mixed forced identities in "+root);if(!replaced&&seen.add(root))keep.add(root.toString());}
  for(String value:order)if(forced.contains(value)&&selected.containsKey(value)){Path pin=selected.get(value);requireIdentity(pin,value);if(seen.add(pin))keep.add(pin.toString());}
  if(selected.containsKey("ZombieBuddy")&&!identities.values().stream().anyMatch(values->values.contains("ZombieBuddy"))){Path loader=selected.get("ZombieBuddy");requireIdentity(loader,"ZombieBuddy");if(seen.add(loader))keep.add(loader.toString());}
  roots.clear();roots.addAll(keep);
 }
 boolean allows(Path jar,String pkg){try{Path path=SafePaths.canonical(jar,true,false);String[] rule=jars.get(path);return !vanilla&&rule!=null&&rule[0].equals(pkg)&&rule[2].equals("true")&&rule[1].equals(sha(path));}catch(Exception error){return false;}}
 void mergeClient(List<String> ids){if(serverComponents!=null)clientSelectionReady=true;if("follow-server".equals(serverComponents))return;if("force-local".equals(serverComponents)){Set<String> seen=new HashSet<String>();List<String> merged=new ArrayList<String>();for(String value:ids)if(seen.add(value.replaceFirst("^\\\\", "")))merged.add(value);for(String value:order)if(!value.equals("OrangeLauncherSession")&&!value.equals("ZombieBuddy")&&components.contains(value)&&seen.add(value))merged.add(value);ids.clear();ids.addAll(merged);return;}Set<String> present=new HashSet<String>();for(String id:ids)present.add(id.replaceFirst("^\\\\", ""));for(String id:order)if(components.contains(id)&&present.add(id))ids.add(id);}
 void normalize(List<String> ids){normalize(ids,override?ordinary:null);}
 void normalize(List<String> ids,List<String> ordinaryOverride){if(serverComponents!=null){ids.clear();if(selected.containsKey("OrangeLauncherSession"))ids.add("OrangeLauncherSession");return;}if(vanilla){ids.clear();ids.addAll(selected.keySet());return;}List<String> input=ordinaryOverride==null?new ArrayList<String>(ids):ordinaryOverride;List<String> result=new ArrayList<String>();Set<String> seen=new HashSet<String>();for(String value:input){String canonical=value.startsWith("\\")?value.substring(1):value;if(!managed.contains(canonical)&&seen.add(canonical))result.add(value);}int cursor=0;for(String component:order){int existing=-1;for(int i=0;i<result.size();i++)if(result.get(i).replaceFirst("^\\\\","").equals(component)){existing=i;break;}if(existing>=0){cursor=Math.max(cursor,existing+1);}else if(components.contains(component)){result.add(cursor++,component);seen.add(component);}}ids.clear();ids.addAll(result);}
}
